      throw new Error(`Unknown field: ${key}`);
    }
  }

  for (const field of known) {
    if (!provided.has(field)) {
      throw new Error(`Missing field: ${field}`);
    }
  }

  const { a, b, operation } = args;

  if (!isNumber(a)) {
    throw new Error('Field "a" must be a number');
  }
  if (!isNumber(b)) {
    throw new Error('Field "b" must be a number');
  }
  if (!OPERATIONS.includes(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  if (operation === 'divide' && b === 0) {
    throw new Error('Division by zero');
  }

  return { a, b, operation };
}

function compute(a, b, operation) {
  switch (operation) {
    case 'add':
      return a + b;
    case 'subtract':
      return a - b;
    case 'multiply':
      return a * b;
    case 'divide':
      return a / b;
    default:
      throw new Error(`Unsupported operation: ${operation}`);
  }
}

export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic calculation on two numbers.',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number', description: 'The first operand.' },
